    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RSI experimental progress</title><style>body{margin:0;background:#f0f4f8;color:#1c2c42;font:16px/1.6 system-ui}header{background:#122c4b;color:white;padding:48px max(24px,calc((100vw - 1180px)/2))}h1{font-size:clamp(28px,4vw,44px);line-height:1.15}main{max-width:1180px;margin:auto;padding:24px}section{background:white;padding:28px;border-radius:14px;margin:20px 0;box-shadow:0 3px 14px #122c4b0c;overflow-wrap:anywhere}h2{font-size:23px}a{color:#17607c}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;border-bottom:1px solid #dde5ee;padding:10px}.tablewrap{overflow:auto}.plot{display:block;width:100%;max-height:480px;object-fit:contain;margin:20px 0}.boundary{border-left:5px solid #d39d35;padding:12px;background:#fff5dd;color:#543800}select{font:inherit;padding:8px}code{overflow-wrap:anywhere}#chart svg{width:100%;height:auto}nav{display:flex;gap:18px;flex-wrap:wrap}header a{color:#d2ebff}small{font-size:13px}@media(max-width:600px){main{padding:10px}section{padding:16px}td,th{padding:7px;font-size:12px}}</style><header><small>RESEARCH ENGINEERING · EVIDENCE-BOUNDED STATUS</small><h1>RSI experimental progress</h1><p>Matched benign feedback, independent semantic review, and clean target adaptation.</p><nav><a href="#section3">Human review</a><a href="#section5">Clean training</a><a href="#section10">Reports</a></nav></header><main>'''
